const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define eastern tropical Pacific region
  var roi = ee.Geometry.Polygon([
    [[-150, 20], [-80, 20], [-80, -20], [-150, -20], [-150, 20]]
  ]);

  // Function to process MODIS SST data
  function processSST(collection) {
    return collection
      .filterBounds(roi)
      .select('sst')
      .map(function(image) {
        // Convert from Kelvin to Celsius and mask poor quality
        var sst = image.select('sst').multiply(0.0001).subtract(273.15);
        return sst.updateMask(sst.gt(-5).and(sst.lt(40))); // Reasonable SST range
      });
  }

  // Get November 2021 SST
  var nov2021 = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate('2021-11-01', '2021-11-30');
  var nov2021_processed = processSST(nov2021);

  // Get long-term November average (2000-2020)
  var longterm = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filter(ee.Filter.calendarRange(11, 11, 'month'))
    .filter(ee.Filter.calendarRange(2000, 2020, 'year'));
  var longterm_processed = processSST(longterm);

  // Check data availability
  var count2021 = nov2021_processed.size().getInfo();
  var countLongterm = longterm_processed.size().getInfo();

  print(`2021 November images: ${count2021}`);
  print(`Long-term November images: ${countLongterm}`);

  if (count2021 === 0 || countLongterm === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Calculate means
  var mean2021 = nov2021_processed.mean();
  var meanLongterm = longterm_processed.mean();

  // Check valid pixels
  var count2021_pixels = mean2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  var countLongterm_pixels = meanLongterm.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  print(`2021 valid pixels: ${count2021_pixels}`);
  print(`Long-term valid pixels: ${countLongterm_pixels}`);

  if (count2021_pixels === 0 || countLongterm_pixels === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Calculate SST values
  var sst2021 = mean2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  var sstLongterm = meanLongterm.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  print(`2021 SST: ${sst2021?.toFixed(2)}°C`);
  print(`Long-term SST: ${sstLongterm?.toFixed(2)}°C`);
  print(`Difference: ${(sst2021 - sstLongterm)?.toFixed(2)}°C`);

  // Validate results
  if (sst2021 === null || sstLongterm === null || 
      isNaN(sst2021) || isNaN(sstLongterm) ||
      sst2021 < -5 || sst2021 > 40 || 
      sstLongterm < -5 || sstLongterm > 40) {
    print("<answer>C3</answer>");
    return;
  }

  // Check if 2021 SST is lower than long-term average
  if (sst2021 < sstLongterm) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
